</head>
<body>
  <main class="card">
    <h1>🌡️ Celsius → Fahrenheit</h1>

    <div class="field">
      <label for="celsius">Celsius (°C)</label>
      <input type="number" id="celsius" step="any" placeholder="e.g. 25" autofocus>
      <div class="error" id="error" role="alert"></div>
    </div>

    <div class="field">
      <label for="fahrenheit">Fahrenheit (°F)</label>
      <div class="result" id="fahrenheit" aria-live="polite">—</div>
    </div>

    <div class="formula">Formula: °F = (°C × 9/5) + 32</div>

    <div class="quick">
      <button data-value="-40">−40 °C</button>
      <button data-value="0">0 °C (freezing)</button>
      <button data-value="20">20 °C (room)</button>
      <button data-value="37">37 °C (body)</button>
      <button data-value="100">100 °C (boiling)</button>
    </div>
  </main>

  <script>
    const celsiusInput = document.getElementById('celsius');
    const fahrenheitOutput = document.getElementById('fahrenheit');
    const errorEl = document.getElementById('error');

    function celsiusToFahrenheit(c) {
      return (c * 9) / 5 + 32;
    }

    function formatNumber(n) {
      // Round to 2 decimal places and drop trailing zeros
      return Number(n.toFixed(2)).toString();
    }

    function update() {
      const raw = celsiusInput.value.trim();

      if (raw === '') {
        fahrenheitOutput.textContent = '—';
        celsiusInput.classList.remove('invalid');
        errorEl.textContent = '';
        return;
      }

      const c = Number(raw);
      if (!Number.isFinite(c)) {
        fahrenheitOutput.textContent = '—';
        celsiusInput.classList.add('invalid');
        errorEl.textContent = 'Please enter a valid number.';
        return;
      }

      celsiusInput.classList.remove('invalid');
      errorEl.textContent = '';
      fahrenheitOutput.textContent = `${formatNumber(celsiusToFahrenheit(c))} °F`;
    }

    celsiusInput.addEventListener('input', update);

    document.querySelectorAll('.quick button').forEach(btn => {
      btn.addEventListener('click', () => {
        celsiusInput.value = btn.dataset.value;
        update();
        celsiusInput.focus();
      });
    });
  </script>
</body>
</html>
```

**How it works:**
- Results update live as you type. No submit button is needed.
- Empty input shows a dash, and non-numeric input shows an error message.
- The result is rounded to two decimal places.
- The quick-select buttons fill in common reference temperatures.
- The layout is responsive, so it works on phones as well as desktops.

