<body>
  <div class="container">
    <h1>My To-Do List</h1>

    <form id="task-form">
      <input type="text" id="task-input" placeholder="What needs doing?" autocomplete="off" required>
      <button type="submit" class="add-btn" aria-label="Add task">+</button>
    </form>

    <div class="filters">
      <button data-filter="all" class="active">All</button>
      <button data-filter="active">Active</button>
      <button data-filter="done">Done</button>
    </div>

    <ul id="task-list"></ul>
    <div id="footer" class="footer"></div>
  </div>

  <script>
    const form = document.getElementById('task-form');
    const input = document.getElementById('task-input');
    const list = document.getElementById('task-list');
    const footer = document.getElementById('footer');
    const filterButtons = document.querySelectorAll('.filters button');

    let tasks = JSON.parse(localStorage.getItem('todo-tasks')) || [];
    let filter = 'all';

    function save() {
      localStorage.setItem('todo-tasks', JSON.stringify(tasks));
    }

    function render() {
      const visible = tasks.filter(t =>
        filter === 'all' ||
        (filter === 'active' && !t.done) ||
        (filter === 'done' && t.done)
      );

      list.innerHTML = '';

      if (visible.length === 0) {
        list.innerHTML = '<div class="empty">' +
          (tasks.length === 0 ? 'No tasks yet. Add one above!' : 'Nothing here.') +
          '</div>';
      }

      visible.forEach(task => {
        const li = document.createElement('li');
        if (task.done) li.classList.add('done');

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.done;
        checkbox.addEventListener('change', () => toggle(task.id));

        const text = document.createElement('span');
        text.className = 'task-text';
        text.textContent = task.text;

        const del = document.createElement('button');
        del.className = 'delete-btn';
        del.textContent = '×';
        del.setAttribute('aria-label', 'Delete task');
        del.addEventListener('click', () => remove(task.id));

        li.append(checkbox, text, del);
        list.appendChild(li);
      });

      const doneCount = tasks.filter(t => t.done).length;
      footer.innerHTML = '';
      if (tasks.length > 0) {
        footer.append(`${tasks.length - doneCount} left · ${doneCount} done`);
        if (doneCount > 0) {
          const clear = document.createElement('button');
          clear.textContent = 'Clear done';
          clear.addEventListener('click', clearDone);
          footer.appendChild(clear);
        }
      }
    }

    function add(text) {
      tasks.push({ id: Date.now().toString(), text, done: false });
      save();
      render();
    }

    function toggle(id) {
      const task = tasks.find(t => t.id === id);
      if (task) task.done = !task.done;
      save();
      render();
    }

    function remove(id) {
      tasks = tasks.filter(t => t.id !== id);
      save();
      render();
    }

    function clearDone() {
      tasks = tasks.filter(t => !t.done);
      save();
      render();
    }

    form.addEventListener('submit', e => {
      e.preventDefault();
      const text = input.value.trim();
      if (!text) return;
      add(text);
      input.value = '';
      input.focus();
    });

    filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        filter = btn.dataset.filter;
        filterButtons.forEach(b => b.classList.toggle('active', b === btn));
        render();
      });
    });

    render();
  </script>
</body>
</html>
