#define SEG_ODDS    (1ULL << 18)    /* odd numbers per segment (256 KiB) */

/* Count primes among odd values lo, lo+2, ..., lo+2(m-1). lo must be odd. */
static uint64_t count_segment(uint64_t lo, uint64_t m,
                              const uint32_t *base, size_t nbase)
{
    uint8_t *buf = malloc(m);
    memset(buf, 1, m);                       /* buf[i] == 1: lo+2i still a candidate */
    uint64_t hi = lo + 2 * (m - 1);

    for (size_t k = 0; k < nbase; k++) {
        uint64_t p = base[k];
        if (p * p > hi) break;

        uint64_t first = ((lo + p - 1) / p) * p;   /* smallest multiple of p >= lo */
        if (!(first & 1)) first += p;              /* make it odd (p is odd) */
        uint64_t start = first < p * p ? p * p : first;

        for (uint64_t v = start; v <= hi; v += 2 * p)
            buf[(v - lo) >> 1] = 0;
    }

    uint64_t cnt = 0;
    for (uint64_t i = 0; i < m; i++) cnt += buf[i];
    free(buf);
    return cnt;
}

int main(void)
{
