            for (uint64_t j = i * i; j <= SQRT_LIMIT; j += i) small[j] = 1;
        }
    }
    free(small);

    /* Odd numbers 3 .. LIMIT-1 */
    uint64_t total = (LIMIT - 2) / 2;
    uint64_t nseg  = (total + SEG_ODDS - 1) / SEG_ODDS;

    uint64_t count = 1;                      /* the prime 2 */

    #pragma omp parallel for schedule(dynamic) reduction(+:count)
    for (uint64_t s = 0; s < nseg; s++) {
