      border-color: #3b82f6;
    }
    .result {
      margin-top: 1.5rem;
      font-size: 1.8rem;
      font-weight: bold;
      color: #1d4ed8;
      min-height: 2.2rem;
    }
    .error {
      color: #b91c1c;
      font-size: 0.95rem;
      min-height: 1.2rem;
      margin-top: 0.5rem;
    }
  </style>
</head>
<body>
  <main class="card">
    <h1>Celsius to Fahrenheit</h1>
    <label for="celsius">Temperature (°C)</label>
    <input type="number" id="celsius" step="any" placeholder="e.g. 25" autofocus>
    <div class="error" id="error"></div>
    <div class="result" id="result"></div>
  </main>

  <script>
    const input = document.getElementById('celsius');
    const result = document.getElementById('result');
    const error = document.getElementById('error');

    function convert() {
      const raw = input.value.trim();

      if (raw === '') {
        result.textContent = '';
        error.textContent = '';
        return;
      }

      const celsius = Number(raw);
      if (!Number.isFinite(celsius)) {
        result.textContent = '';
        error.textContent = 'Please enter a valid number.';
        return;
      }

      const fahrenheit = celsius * 9 / 5 + 32;
      error.textContent = '';
      result.textContent = `${fahrenheit.toFixed(1)} °F`;
    }

    input.addEventListener('input', convert);
  </script>
</body>
</html>
```

**How it works**
- Type a Celsius value and the Fahrenheit result updates as you type.
- The formula is °F = °C × 9/5 + 32.
- Results are shown to one decimal place.
- Empty or non-numeric input shows an error message instead of a result.

